/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}

const PROJECT_KEY_MAX = 4;

/**
 * Makes a project key unique inside one workspace the same way `uniqueSlug`
 * makes an address unique: append 2, 3, … and trim the stem so the result
 * never exceeds four characters (`WV` + `2` → `WV2`, `TASK` + `2` → `TAS2`).
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const base =
    key.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX) || "TASK";
  const used = new Set(Array.from(taken, (item) => item.toUpperCase()));
  const free = (candidate: string): boolean =>
    candidate.length >= 2 &&
    candidate.length <= PROJECT_KEY_MAX &&
    /^[A-Z][A-Z0-9]*$/.test(candidate) &&
    !used.has(candidate);

  if (free(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    const candidate = `${base.slice(0, PROJECT_KEY_MAX - tail.length)}${tail}`;
    if (free(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique project keys");
}

