/**
 * Counts the organization's projects; the `projects` quota reads this.
 * Only live projects occupy a plan slot — archiving frees the slot at once.
 * Pass `{ includeArchived: true }` to count every row.
 */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        ...compact(
          orgPredicate(projects.orgId, orgId),
          livePredicate(projects.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

