const PROJECT_KEY_MAX = 4;

/**
 * Makes a project key unique inside one workspace the same way `uniqueSlug`
 * makes an address unique: append 2, 3, … and trim the stem so the result
 * never exceeds four characters (`WV` + `2` → `WV2`, `TASK` + `2` → `TAS2`).
